def pmtt(h, rate, nper, pv, fv):
    """A table for solving the payment: the FV table of the course, with fv typed in and pmt as the target."""
    d = {'A1': 'הנתון', 'B1': 'שם', 'C1': h}
    for k, (he, en) in enumerate(FVROWS):
        d[f'A{2 + k}'] = he; d[f'B{2 + k}'] = en
    d.update({'C2': rate, 'C3': nper, 'C5': pv, 'C6': fv})
    return d, {'C4': '=PMT(C2,C3,C5,C6)'}, {'C2': _pctf(rate), 'C4': 'num2', 'C5': 'num0', 'C6': 'num0'}


